INSERT INTO public.courses (id, title, level, description, symbol, position, min_level) VALUES
 ('11111111-1111-1111-1111-111111111111','Álgebra Básica','basico','Variables, términos semejantes y ecuaciones de uno y dos pasos.','x',1,1),
 ('22222222-2222-2222-2222-222222222222','Álgebra Intermedia','intermedio','Ecuaciones lineales, desigualdades y sistemas de dos incógnitas.','∑',2,2),
 ('33333333-3333-3333-3333-333333333333','Álgebra Avanzada','avanzado','Factorización, productos notables y ecuaciones cuadráticas.','∫',3,3);

INSERT INTO public.lessons (id, course_id, title, description, concept, position) VALUES
 ('10000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','Variables y expresiones','Leer una situación y escribirla como expresión algebraica.','Traducción a lenguaje algebraico',1),
 ('10000000-0000-0000-0000-000000000002','11111111-1111-1111-1111-111111111111','Términos semejantes','Agrupar solo lo que comparte la misma parte literal.','Reducción de términos',2),
 ('10000000-0000-0000-0000-000000000003','11111111-1111-1111-1111-111111111111','Ecuaciones de un paso','Deshacer una sola operación conservando la igualdad.','Operación inversa',3),
 ('10000000-0000-0000-0000-000000000004','11111111-1111-1111-1111-111111111111','Ecuaciones de dos pasos','Ordenar dos operaciones inversas para despejar la incógnita.','Despeje en dos pasos',4),
 ('10000000-0000-0000-0000-000000000005','22222222-2222-2222-2222-222222222222','Ecuaciones lineales','Incógnitas en ambos lados y paréntesis.','Equivalencia de ecuaciones',1),
 ('10000000-0000-0000-0000-000000000006','22222222-2222-2222-2222-222222222222','Desigualdades','Resolver y saber cuándo se invierte el sentido.','Orden y desigualdad',2),
 ('10000000-0000-0000-0000-000000000007','22222222-2222-2222-2222-222222222222','Sistemas de ecuaciones','Dos condiciones simultáneas, una sola solución.','Sustitución y eliminación',3),
 ('10000000-0000-0000-0000-000000000008','33333333-3333-3333-3333-333333333333','Productos y factorización','Reconocer estructuras y devolverlas a forma de producto.','Estructura multiplicativa',1),
 ('10000000-0000-0000-0000-000000000009','33333333-3333-3333-3333-333333333333','Ecuaciones cuadráticas','Resolver por factorización y por fórmula general.','Raíces de un polinomio de grado 2',2);

INSERT INTO public.exercises (lesson_id, title, problem, equation, answer, difficulty, xp, concept, hints, diagnostic, transfer_problem, transfer_answer, ask_reasoning, independent, position) VALUES
 ('10000000-0000-0000-0000-000000000001','El triple más dos','Escribe el valor de la expresión 3n + 2 cuando n = 4.','3n + 2,  n = 4','14','facil',10,'Evaluar una expresión',
  ARRAY['Sustituye la letra por el número antes de operar.','Estás evaluando una expresión: primero sustitución, después operaciones.','Reemplaza n por 4 dentro de la expresión.','3·4 da un producto; falta sumar el término independiente.','3·4 = 12, y 12 + 2 = 14.'],
  'Sustituiste bien, pero el orden de las operaciones cambió el resultado: la multiplicación ocurre antes que la suma.',
  'Un taxi cobra $2 de banderazo más $3 por kilómetro. ¿Cuánto cuesta un viaje de 4 km?','14',true,false,1),
 ('10000000-0000-0000-0000-000000000001','Traducir una frase','Un número disminuido en 7 da 15. ¿Cuál es el número?','n − 7 = 15','22','facil',10,'Traducción a lenguaje algebraico',
  ARRAY['"Disminuido en" indica una resta sobre el número desconocido.','El enunciado describe una igualdad, no solo una expresión.','Escribe n − 7 = 15 y despeja n.','Para deshacer una resta se suma la misma cantidad en ambos lados.','n = 15 + 7 = 22.'],
  'La operación elegida deshace mal la resta: al mover el 7 al otro lado cambia de signo.',
  'Después de gastar $7 te quedan $15. ¿Cuánto tenías?','22',false,false,2),
 ('10000000-0000-0000-0000-000000000001','Reto independiente: expresiones','Sin pistas: evalúa 5a − 3 cuando a = 6.','5a − 3,  a = 6','27','media',30,'Evaluar una expresión',
  ARRAY[]::text[], NULL, NULL, NULL, false, true, 3),

 ('10000000-0000-0000-0000-000000000002','Reducir la expresión','Reduce 4x + 3x − 2x.','4x + 3x − 2x','5x','facil',10,'Términos semejantes',
  ARRAY['Todos los términos comparten la misma letra.','Solo se suman los coeficientes; la parte literal se conserva.','Opera 4 + 3 − 2 y conserva la x.','El resultado tiene la forma (número)x.','4 + 3 − 2 = 5, así que queda 5x.'],
  'El resultado perdió o cambió la parte literal: al sumar términos semejantes la letra permanece igual.',
  'Compraste 4 cajas, te regalaron 3 y devolviste 2. Si cada caja trae x piezas, ¿cuántas piezas tienes?','5x',false,false,1),
 ('10000000-0000-0000-0000-000000000002','No todo se suma','Reduce 2x + 5 + 3x − 2 y escribe el coeficiente de x.','2x + 5 + 3x − 2','5','media',10,'Términos semejantes',
  ARRAY['Hay dos grupos distintos: términos con x y términos sin x.','Los números sueltos no se combinan con los que llevan x.','Agrupa 2x con 3x por un lado.','2x + 3x da un único término con x.','El coeficiente pedido es 5 (la expresión queda 5x + 3).'],
  'Parece que mezclaste términos con x y constantes: solo se agrupa lo que comparte la misma parte literal.',
  'En una mochila hay 2 paquetes de x lápices, 5 sueltos, 3 paquetes más y usaste 2 sueltos. ¿Cuántos paquetes completos hay?','5',true,false,2),
 ('10000000-0000-0000-0000-000000000002','Reto independiente: reducción','Sin pistas: reduce 7m − 2m + m y escribe el coeficiente.','7m − 2m + m','6','media',30,'Términos semejantes',
  ARRAY[]::text[], NULL, NULL, NULL, false, true, 3),

 ('10000000-0000-0000-0000-000000000003','Deshacer una suma','Resuelve x + 9 = 21.','x + 9 = 21','12','facil',10,'Operación inversa',
  ARRAY['La igualdad es una balanza: lo que hagas de un lado, hazlo del otro.','El 9 está sumando a la incógnita.','Aplica la operación inversa de la suma en ambos lados.','Resta 9 a ambos lados: x = 21 − 9.','x = 12.'],
  'Tu procedimiento apunta al despeje, pero la operación aplicada no deshace la suma.',
  'Ya llevas 9 páginas leídas de un capítulo de 21. ¿Cuántas te faltan?','12',false,false,1),
 ('10000000-0000-0000-0000-000000000003','Deshacer un producto','Resuelve 6x = 54.','6x = 54','9','facil',10,'Operación inversa',
  ARRAY['El 6 multiplica a la incógnita.','La operación inversa del producto es la división.','Divide ambos lados entre 6.','x = 54 ÷ 6.','x = 9.'],
  'Restar no deshace una multiplicación: revisa qué operación está afectando a la x.',
  'Seis amigos pagan $54 en partes iguales. ¿Cuánto aporta cada uno?','9',false,false,2),
 ('10000000-0000-0000-0000-000000000003','Reto independiente: un paso','Sin pistas: resuelve x − 14 = 6.','x − 14 = 6','20','media',30,'Operación inversa',
  ARRAY[]::text[], NULL, NULL, NULL, false, true, 3),

 ('10000000-0000-0000-0000-000000000004','Dos pasos clásicos','Resuelve 3x + 5 = 20.','3x + 5 = 20','5','media',10,'Despeje en dos pasos',
  ARRAY['Hay dos operaciones afectando a la x: una suma y un producto.','Se elimina primero el término independiente.','¿Qué operación necesitas aplicar para eliminar el +5?','Resta 5 en ambos lados: queda 3x = 15.','Divide entre 3: x = 5.'],
  'Tu procedimiento va en la dirección correcta, pero después de despejar queda una diferencia: revisa el paso donde eliminas el +5.',
  'Una tienda cobra una cuota fija de $5 más $3 por artículo. Si el total es $20, ¿cuántos artículos se compraron?','5',true,false,1),
 ('10000000-0000-0000-0000-000000000004','Con resta y división','Resuelve 4x − 7 = 13.','4x − 7 = 13','5','media',10,'Despeje en dos pasos',
  ARRAY['Primero neutraliza el término sin x.','El −7 se elimina sumando 7 en ambos lados.','Al sumar 7 queda 4x = 20.','Ahora deshaz la multiplicación.','x = 20 ÷ 4 = 5.'],
  'El orden de los pasos alteró el resultado: elimina primero el término independiente y después el coeficiente.',
  'Un repartidor gana $4 por entrega y paga $7 de gasolina; hoy le quedaron $13 netos. ¿Cuántas entregas hizo?','5',false,false,2),
 ('10000000-0000-0000-0000-000000000004','Reto independiente: dos pasos','Sin pistas: resuelve 5x + 8 = 43.','5x + 8 = 43','7','dificil',30,'Despeje en dos pasos',
  ARRAY[]::text[], NULL, NULL, NULL, false, true, 3),

 ('10000000-0000-0000-0000-000000000005','Incógnita en ambos lados','Resuelve 5x − 4 = 3x + 8.','5x − 4 = 3x + 8','6','media',10,'Equivalencia de ecuaciones',
  ARRAY['La x aparece en los dos lados de la igualdad.','Agrupa las x de un lado y los números del otro.','Resta 3x en ambos lados.','Queda 2x − 4 = 8, luego 2x = 12.','x = 6.'],
  'Al mover un término cruzó la igualdad sin cambiar de signo: revisa ese paso.',
  'Dos planes: uno cobra $5 por hora menos $4 de descuento; otro $3 por hora más $8 fijos. ¿A cuántas horas cuestan lo mismo?','6',true,false,1),
 ('10000000-0000-0000-0000-000000000005','Con paréntesis','Resuelve 2(x + 3) = 16.','2(x + 3) = 16','5','media',10,'Propiedad distributiva',
  ARRAY['El paréntesis está multiplicado por 2.','Puedes distribuir o dividir ambos lados entre 2.','Dividiendo entre 2: x + 3 = 8.','Ahora es una ecuación de un paso.','x = 5.'],
  'La distribución quedó incompleta: el factor externo multiplica a cada término del paréntesis.',
  'Dos cajas contienen lo mismo: x libros más 3 revistas cada una. En total hay 16 objetos. ¿Cuántos libros trae cada caja?','5',false,false,2),
 ('10000000-0000-0000-0000-000000000005','Reto independiente: lineales','Sin pistas: resuelve 7x + 2 = 4x + 20.','7x + 2 = 4x + 20','6','dificil',30,'Equivalencia de ecuaciones',
  ARRAY[]::text[], NULL, NULL, NULL, false, true, 3),

 ('10000000-0000-0000-0000-000000000006','Desigualdad simple','Resuelve 2x + 1 < 9 y escribe el mayor entero que la cumple.','2x + 1 < 9','3','media',10,'Orden y desigualdad',
  ARRAY['Trátala como una ecuación mientras no multipliques por un negativo.','Resta 1 en ambos lados.','Queda 2x < 8, es decir x < 4.','Buscan el mayor entero estrictamente menor que 4.','La respuesta es 3.'],
  'El límite quedó incluido: la desigualdad es estricta, así que el valor frontera no cumple.',
  'Con $9 y una entrada de $1 de acceso, cada boleto cuesta $2. ¿Cuántos boletos completos puedes comprar sin gastar los $9?','3',false,false,1),
 ('10000000-0000-0000-0000-000000000006','Cuando se invierte el signo','Resuelve −3x > 12 y escribe el valor frontera de x.','−3x > 12','-4','dificil',20,'Orden y desigualdad',
  ARRAY['El coeficiente de x es negativo.','Dividir entre un negativo cambia el sentido de la desigualdad.','Divide ambos lados entre −3 e invierte el signo.','Queda x < −4.','El valor frontera es −4.'],
  'El sentido de la desigualdad no se actualizó al dividir entre un número negativo.',
  NULL,NULL,true,false,2),
 ('10000000-0000-0000-0000-000000000006','Reto independiente: desigualdades','Sin pistas: resuelve 5x − 3 ≤ 12 y escribe el mayor entero que la cumple.','5x − 3 ≤ 12','3','dificil',30,'Orden y desigualdad',
  ARRAY[]::text[], NULL, NULL, NULL, false, true, 3),

 ('10000000-0000-0000-0000-000000000007','Sistema por sustitución','Resuelve el sistema y escribe el valor de x:  x + y = 10,  y = x + 2.','x + y = 10;  y = x + 2','4','media',10,'Sustitución',
  ARRAY['Ya tienes y expresada en términos de x.','Sustituye esa expresión en la primera ecuación.','Queda x + (x + 2) = 10.','2x + 2 = 10, entonces 2x = 8.','x = 4.'],
  'La sustitución dejó fuera un término: al reemplazar y hay que conservar todo el paréntesis.',
  'Dos hermanos suman 10 años de diferencia total en un juego; el mayor tiene 2 puntos más. ¿Cuántos puntos tiene el menor?','4',true,false,1),
 ('10000000-0000-0000-0000-000000000007','Reto independiente: sistemas','Sin pistas: resuelve  2x + y = 13,  y = 3  y escribe x.','2x + y = 13;  y = 3','5','dificil',30,'Sustitución',
  ARRAY[]::text[], NULL, NULL, NULL, false, true, 2),

 ('10000000-0000-0000-0000-000000000008','Producto notable','Desarrolla (x + 4)² y escribe el coeficiente del término lineal.','(x + 4)²','8','media',10,'Binomio al cuadrado',
  ARRAY['Un binomio al cuadrado no es la suma de los cuadrados.','La estructura es a² + 2ab + b².','Aquí a = x y b = 4.','El término lineal es 2·x·4.','El coeficiente es 8.'],
  'Falta el doble producto: (a + b)² incluye el término 2ab.',
  'El área de un cuadrado cuyo lado mide x + 4 aumenta respecto a x². ¿Cuál es el coeficiente de x en ese aumento?','8',false,false,1),
 ('10000000-0000-0000-0000-000000000008','Factorizar una diferencia','Factoriza x² − 25 y escribe el valor positivo que anula la expresión.','x² − 25','5','media',10,'Diferencia de cuadrados',
  ARRAY['Ambos términos son cuadrados perfectos.','La estructura es a² − b² = (a + b)(a − b).','Aquí a = x y b = 5.','Los factores son (x + 5)(x − 5).','La raíz positiva es 5.'],
  'La factorización elegida no reproduce la expresión original al multiplicarla de vuelta.',
  NULL,NULL,true,false,2),

 ('10000000-0000-0000-0000-000000000009','Cuadrática por factorización','Resuelve x² − 5x + 6 = 0 y escribe la raíz mayor.','x² − 5x + 6 = 0','3','dificil',20,'Raíces por factorización',
  ARRAY['Busca dos números que multiplicados den 6.','Esos mismos números deben sumar −5.','Los números son −2 y −3.','La factorización es (x − 2)(x − 3) = 0.','Las raíces son 2 y 3; la mayor es 3.'],
  'Los factores propuestos no reproducen el término lineal: revisa la suma de los dos números.',
  'Un terreno rectangular tiene lados x−2 y x−3 metros y área nula al reducirse. ¿Cuál es el mayor valor de x que lo anula?','3',true,false,1),
 ('10000000-0000-0000-0000-000000000009','Reto independiente: cuadráticas','Sin pistas: resuelve x² − 9 = 0 y escribe la raíz positiva.','x² − 9 = 0','3','dificil',30,'Raíces de un polinomio de grado 2',
  ARRAY[]::text[], NULL, NULL, NULL, false, true, 2);
